type DebounceFunction<T extends (...args: any[]) => any> =
  & typeof fn
  & { cancel: () => void; flush: () => void }

function debounce<T extends (...args: any[]) => any>(
  fn: T,
  delay: number
): DebounceFunction<T> {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  let lastCallTime: number | null = null;
  let lastArgs: any[] | null = null;
  let lastThis: any | null = null;

  const debounced = function (this: any, ...args: Parameters<T>) {
    const callNow = !timeoutId && !lastCallTime;
    const now = Date.now();

    lastArgs = args;
    lastThis = this;
    lastCallTime = now;

    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (!callNow) {
        fn.apply(lastThis, lastArgs);
      }
      lastArgs = null;
      lastThis = null;
      lastCallTime = null;
    }, delay);

    if (callNow && !timeoutId) {
      fn.apply(lastThis, args);
    }
  } as DebounceFunction<T>;

  debounced.cancel = function () {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
      lastArgs = null;
      lastThis = null;
      lastCallTime = null;
    }
  };

  debounced.flush = function () {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
      if (lastArgs !== null && lastThis !== null) {
        fn.apply(lastThis, lastArgs);
        lastArgs = null;
        lastThis = null;
        lastCallTime = null;
      }
    }
  };

  return debounced;
}
```

